import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { Link } from 'react-router-dom';

function EventList() {
  const [events, setEvents] = useState([]);
  const [search, setSearch] = useState('');

  useEffect(() => {
    async function fetchEvents() {
      const res = await axios.get('/api/v1/events');
      setEvents(res.data.events); // adjust based on your API's structure
    }
    fetchEvents();
  }, []);

  // Filtered events by search
  const filtered = events.filter(event =>
    event.title.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div>
      <h2>Approved Events</h2>
      <input
        placeholder="Search events"
        value={search}
        onChange={e => setSearch(e.target.value)}
        style={{ marginBottom: 10 }}
      />
      <div>
        {filtered.map(event => (
          <div key={event._id} style={{ border: '1px solid #ddd', margin: 10, padding: 10 }}>
            <Link to={`/events/${event._id}`}>
              <h3>{event.title}</h3>
            </Link>
            <p>Date: {event.date}</p>
            <p>Location: {event.location}</p>
            <p>Price: ${event.price}</p>
            <p>Status: {event.status}</p>
            <p>Tickets Left: {event.tickets - event.ticketsBooked}</p>
          </div>
        ))}
      </div>
    </div>
  );
}

export default EventList;
